export const currencyReturnDefinitions={
  currencyReturn:{title:'Explore a hypothetical unhedged foreign-currency investment',fields:[
    ['initial','Starting investment measured in CAD',10000,0,1000000,1000],
    ['assetReturn','Assumed annual asset return in its foreign currency (%)',10,-30,30,1],
    ['fxChange','Annual change in CAD value of one foreign currency unit (%)',-10,-30,30,1],
    ['years','Years of repeating the same two annual assumptions',5,1,10,1]
  ]}
};
export function translatedReturn(assetReturn,fxChange){return (1+assetReturn/100)*(1+fxChange/100)-1;}
export function currencyValue(initial,assetReturn,fxChange,years){return initial*((1+assetReturn/100)*(1+fxChange/100))**years;}
export function currencyReturnResult(kind,input){
  if(kind!=='currencyReturn')throw Error('Unknown currency-return topic.');
  const a=input.assetReturn/100,f=input.fxChange/100,r=translatedReturn(input.assetReturn,input.fxChange),end=currencyValue(input.initial,input.assetReturn,input.fxChange,input.years);
  return {metrics:[['Assumed one-year asset return in foreign currency',a,'percent'],['One-year return after CAD currency translation',r,'percent'],['CAD investment value after the selected repeated years',end,'money']],note:'Original hypothetical comparison in nominal CAD. One unhedged foreign-currency asset exposure is purchased at the start, with no additional deposits or withdrawals. The local-currency asset return is a total-return assumption with any distributions reinvested locally. Currency change always means the percentage change in CAD per one foreign currency unit: a positive value raises each foreign unit’s CAD value; a negative value reduces it. The same two annual factors repeat for the selected years, with no probabilities or forecast claim. The unchanged-currency comparator holds the currency quote constant and is not the result of a modeled hedge. No trading or conversion charges, taxes, inflation, borrowing, currency controls or fund-specific exposures are calculated. All values are scenario assumptions, not historical performance or current exchange-rate quotes.',charts:[
    {id:'currency-return-path',type:'line',title:'The asset’s local gain and its CAD value can move differently',unit:'money',xLabel:'Complete model years',series:[{name:'CAD value with the selected currency change',rows:Array.from({length:input.years+1},(_,x)=>({x,value:currencyValue(input.initial,input.assetReturn,input.fxChange,x)}))},{name:'CAD value with an unchanged currency quote',rows:Array.from({length:input.years+1},(_,x)=>({x,value:currencyValue(input.initial,input.assetReturn,0,x)})),dash:true}],note:'Both lines start with the same CAD amount and use the same foreign-currency asset return. The only difference is the exchange-rate factor. These are annual endpoints under repeated constant assumptions, not an observed path or a hedge-cost comparison. The unchanged-quote line is also in CAD; it does not add foreign units to Canadian dollars.'},
    {id:'currency-return-one-year',type:'waterfall',title:'Reconcile one year, including the asset–currency interaction',unit:'money',rows:[{label:'Starting CAD investment',value:input.initial},{label:'Asset return on the opening amount',value:input.initial*a},{label:'Currency change on the opening amount',value:input.initial*f},{label:'Interaction of the two changes',value:input.initial*a*f}],totalLabel:'CAD value after one year',note:'This bridge always covers one year, even when the selected path is longer. Its arithmetic is initial × [1 + asset return + currency change + asset return × currency change]. The interaction is part of the translation calculation, not a separate fee, trade or second asset. Signed steps can add or subtract from the value.'},
    {id:'currency-return-horizons',type:'groupbar',title:'Keep the same asset assumption while varying only the currency path',unit:'money',unitLabel:'CAD investment value at each stated horizon',seriesNames:['−10% currency change each year','Unchanged currency quote','+10% currency change each year'],rows:[1,3,5,10].map(years=>({label:years+' '+(years===1?'year':'years'),values:[-10,0,10].map(fx=>currencyValue(input.initial,input.assetReturn,fx,years))})),note:'Every row uses the entered starting CAD amount and asset return, with three fixed alternative currency assumptions. The displayed horizons replace the selected year control. They are scenarios with no assigned likelihood and no claim that exchange rates usually follow a constant path. A positive currency change here means more CAD per foreign unit.'},
    {id:'currency-return-factor-grid',type:'heatmap',signed:true,compactValues:false,title:'Combine the two one-year changes multiplicatively',unit:'percent',unitLabel:'One-year CAD return; columns: change in CAD per foreign unit (%)',columns:['−20%','−10%','0%','10%'],rows:[-20,0,10,20].map(asset=>({label:'Asset '+asset+'%',values:[-20,-10,0,10].map(fx=>translatedReturn(asset,fx))})),note:'Rows replace the foreign-currency asset return; columns replace the currency change. Each cell equals (1 + asset return) × (1 + currency change) − 1. The fixed matrix is independent of the controls and describes one year, not the selected multi-year cumulative return. Gold and teal distinguish negative and positive CAD returns; they do not indicate scenario probabilities.'}
  ]};
}
